using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Text;
using System.Linq;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        if (EditorApplication.isPlaying)
        {
            EditorApplication.isPlaying = false;
            ctx.ReturnValue = "exited play, re-run";
            return;
        }

        var scene = EditorSceneManager.GetActiveScene();
        if (!scene.path.Contains("GameLobby"))
            scene = EditorSceneManager.OpenScene("Assets/Project/GameLobby.unity");

        Transform FindDeep(string name)
        {
            foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
            {
                if (EditorUtility.IsPersistent(t.gameObject)) continue;
                if (t.name == name) return t;
            }
            return null;
        }

        sb.AppendLine("precheck yellow=" + FindDeep("Yellow_HUD_Root")?.gameObject.activeSelf);
        sb.AppendLine("precheck legacy=" + FindDeep("Canvas_Lobby_Legacy")?.gameObject.activeSelf);
        sb.AppendLine("precheck toolkit=" + FindDeep("UI_Toolkit_Lobby_Root")?.gameObject.activeSelf);
        sb.AppendLine("precheck stage=" + FindDeep("LobbyCharacterStage")?.gameObject.activeSelf);
        sb.AppendLine("precheck reachCanvas=" + FindDeep("Canvas - Main Menu")?.gameObject.activeSelf);

        // Ensure Multiplayer panel manager will open - check Top Panels Searching Games exists
        sb.AppendLine("searching=" + (FindDeep("Searching Games") != null));

        EditorApplication.isPlaying = true;
        ctx.ReturnValue = sb.ToString() + "\nentered play";
    }
}
